const page="<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#722f3f\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-title\" content=\"调一杯\"><link rel=\"manifest\" href=\"/manifest.json\"><link rel=\"apple-touch-icon\" href=\"/icon.png\"><title>调一杯 · 你的居家调酒灵感</title><style>\n*{box-sizing:border-box}body{margin:0;background:#faf8f3;color:#302b2a;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #c8a05c;outline-offset:3px}button{border:0}header{height:88px;border-bottom:1px solid #e8e3db;display:flex;align-items:center;justify-content:space-between;max-width:1240px;margin:auto;padding:0 40px}.brand{font-size:25px;letter-spacing:3px;font-weight:800;color:#722f3f}.brand small{display:block;font-size:9px;letter-spacing:3px;margin-top:4px}nav{display:flex;gap:30px}nav button{background:none;color:#807570;padding:12px 0}nav button.active{color:#722f3f;border-bottom:2px solid #722f3f}.pill{border:1px solid #ddd4c9;border-radius:30px;padding:8px 15px;font-size:12px;color:#746b62}main{max-width:1160px;margin:auto;padding:40px 0 100px}.hero{display:grid;grid-template-columns:1.1fr 1fr;background:#eee9df;border-radius:6px;overflow:hidden;min-height:330px}.hero-copy{padding:43px 48px}.eyebrow{font-size:11px;letter-spacing:3px;color:#836449}.hero h1{font-family:Georgia,serif;font-size:46px;font-weight:500;line-height:1.3;margin:20px 0 15px;letter-spacing:2px}.hero p{font-size:14px;color:#80766f;line-height:1.9}.primary{background:#722f3f;color:white;padding:13px 24px;border-radius:4px;font-size:14px}.hero-art{position:relative;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,#e1cbb1, #d8c9b7);overflow:hidden}.hero-art:after{content:'THE ART OF A GOOD DRINK';position:absolute;bottom:23px;font-size:9px;letter-spacing:4px;color:#766351}.hero-art svg{height:285px;filter:drop-shadow(12px 20px 12px #483a4b30)}.toolbar{display:flex;align-items:end;justify-content:space-between;margin:38px 0 20px}h2{font-family:Georgia,serif;font-size:26px;font-weight:500;margin:0 0 7px} .sub{font-size:12px;color:#92877e}.search{background:#fff;border:1px solid #e5dfd6;border-radius:4px;padding:12px 16px;width:260px}.filters{display:flex;gap:9px;overflow:auto;padding:0 0 23px}.filters button{flex-shrink:0;padding:9px 19px;border-radius:25px;background:#eeeae3;color:#7a716a;font-size:12px}.filters .active{background:#722f3f;color:white}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:23px}.card{border:1px solid #e8e1d7;background:white;border-radius:5px;overflow:hidden;cursor:pointer;transition:transform .2s}.card:hover{transform:translateY(-4px)}.art{height:205px;position:relative;display:flex;justify-content:center;align-items:center;background:var(--bg)}.art svg{height:180px;filter:drop-shadow(8px 12px 7px #55443525)}.save{position:absolute;right:12px;top:12px;background:#ffffffc9;border-radius:50%;width:32px;height:32px;color:#722f3f;font-size:19px}.cardbody{padding:18px}.en{font-size:9px;letter-spacing:1.5px;color:#a29385}.card h3{font-size:18px;margin:6px 0 10px;font-weight:600}.tags{font-size:11px;color:#8a7f73;display:flex;justify-content:space-between}.bottom-note{display:flex;justify-content:space-between;margin-top:35px;padding:20px 0;border-top:1px solid #e5dfd6;color:#948a80;font-size:11px}.empty{padding:50px;text-align:center;color:#8a7f73;grid-column:1/-1}.modal{position:fixed;inset:0;background:#241c22aa;z-index:10;overflow:auto;padding:35px 16px;display:none}.modal.open{display:block}.sheet{max-width:760px;margin:auto;background:#faf8f3;border-radius:12px;padding:30px;position:relative}.close{position:absolute;right:16px;top:14px;border-radius:50%;background:#eee6dc;width:32px;height:32px;font-size:22px;z-index:2}.detailtop{display:grid;grid-template-columns:1fr 1fr;gap:25px;align-items:center}.detailtop .art{border-radius:6px;height:240px}.detailtop h2{font-size:32px;margin:10px 0}.desc{line-height:1.8;color:#887b70;font-size:13px}.section{margin-top:28px}.section h3{font-size:17px}.ingredients{background:white;padding:10px 20px;border-radius:6px}.ingredient{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #eee8df;font-size:14px}.steps{padding:0;list-style:none;counter-reset:s}.steps li{counter-increment:s;padding:12px 0;display:flex;gap:15px;line-height:1.7;font-size:14px}.steps li:before{content:counter(s);flex-shrink:0;display:grid;place-items:center;background:#eae0d6;color:#722f3f;width:28px;height:28px;border-radius:50%}.comment{background:white;padding:15px;border-radius:5px;margin:10px 0}.comment img{max-height:220px;max-width:100%;border-radius:6px;margin-top:10px}.comment p{white-space:pre-wrap;line-height:1.6;font-size:14px}form{display:grid;gap:10px}form input,form textarea,form select{border:1px solid #dfd5ca;border-radius:5px;padding:12px;background:white;width:100%}form textarea{min-height:85px}label{font-size:12px;color:#7e7167}.toast{position:fixed;bottom:35px;left:50%;transform:translateX(-50%);background:#30252c;color:white;border-radius:30px;padding:12px 22px;font-size:13px;z-index:30;display:none}.mobile-nav{display:none}.community-head{padding:20px 0 30px}.community-grid{columns:3;column-gap:20px}.community-grid .comment{break-inside:avoid;border:1px solid #eee3d8}.community-grid img{max-height:none;width:100%}.instruction{padding:15px;background:#eee9df;color:#827365;border-radius:5px;font-size:12px;line-height:1.8}.hidden{display:none!important}#status{font-size:12px;color:#956849}.timer{background:#eee6db;color:#722f3f;padding:10px 16px;border-radius:5px;margin:12px 0} .postbutton{float:right}\n@media(max-width:800px){header{height:72px;padding:0 20px}nav{gap:18px}header .pill{display:none}main{padding:22px 20px 110px}.hero-copy{padding:28px}.hero h1{font-size:34px}.hero-art svg{height:240px}.grid{grid-template-columns:repeat(2,1fr);gap:15px}.community-grid{columns:2}.hero{min-height:290px}.art{height:190px}.hero p{font-size:12px}.search{width:220px}}\n@media(max-width:500px){header nav{display:none}.brand{font-size:22px}header:after{content:'MAKE. SIP. SHARE.';font-size:9px;letter-spacing:1.5px;color:#9a897a}main{padding:18px 16px 100px}.hero{min-height:276px;grid-template-columns:1.2fr 1fr}.hero-copy{padding:26px 0 26px 21px;z-index:1}.hero h1{font-size:29px;letter-spacing:0;margin-top:18px}.hero p{font-size:11px;line-height:1.8}.hero .primary{font-size:12px;padding:11px 15px}.hero-art svg{height:230px;width:170px;max-width:none}.hero-art:after{font-size:6px;letter-spacing:1px;bottom:17px}.eyebrow{font-size:8px;letter-spacing:1.4px}.toolbar{display:block;margin-top:28px}.toolbar h2{font-size:24px}.search{width:100%;margin-top:17px}.filters{gap:7px;padding-bottom:16px}.filters button{padding:9px 15px}.grid{gap:12px}.art{height:170px}.art svg{height:155px}.cardbody{padding:13px}.card h3{font-size:16px}.tags{font-size:10px}.en{font-size:8px}.bottom-note{display:block;line-height:2}.mobile-nav{display:flex;position:fixed;bottom:0;left:0;right:0;justify-content:space-around;background:#faf8f3ed;backdrop-filter:blur(15px);border-top:1px solid #e4ddd3;padding:10px 0 calc(10px + env(safe-area-inset-bottom));z-index:4}.mobile-nav button{background:none;color:#9a8a7b;font-size:11px;min-width:70px}.mobile-nav b{display:block;font-size:21px;font-weight:400;margin-bottom:4px}.mobile-nav .active{color:#722f3f}.sheet{padding:23px 18px}.modal{padding:12px 8px}.detailtop{gap:15px}.detailtop .art{height:200px}.detailtop h2{font-size:25px}.detailtop .art svg{height:170px}.community-grid{columns:1}.postbutton{float:none;margin-top:15px}}\n\n.drink-photo{width:100%;height:100%;display:block;object-fit:cover;transition:transform .4s ease}.card:hover .drink-photo{transform:scale(1.035)}.art{overflow:hidden}.hero-art .drink-photo{position:absolute;inset:0;object-position:center 53%;filter:none}.hero-art:after{background:#302b2a66;color:white;bottom:0;left:0;right:0;padding:18px;text-align:center;content:'MOJITO · 从你的第一杯开始';font-size:10px;letter-spacing:2px}.detailtop .art{height:280px}.sources{font-size:11px;color:#958579;line-height:1.9;margin-top:12px;overflow-wrap:anywhere}.sources a{color:#865361;text-decoration:none}.sources a:hover{text-decoration:underline}\n@media(max-width:500px){.hero-art .drink-photo{object-position:50% center}.hero-art:after{font-size:8px;letter-spacing:0;padding:12px 5px}.detailtop .art{height:220px}.hero{grid-template-columns:1.15fr 1fr}.art{height:190px}}@media(prefers-reduced-motion:reduce){.card,.drink-photo{transition:none}}\n</style></head><body><header><div class=\"brand\">调一杯<small>COCKTAIL STUDIO</small></div><nav id=\"nav\"><button class=\"active\" data-view=\"explore\">探索酒单</button><button data-view=\"community\">微醺广场</button><button data-view=\"saved\">我的收藏</button></nav><span class=\"pill\">一杯灵感，自己调。</span></header><main><section id=\"hero\" class=\"hero\"><div class=\"hero-copy\"><div class=\"eyebrow\">YOUR HOME BAR STARTS HERE</div><h1>把生活，<br>调成喜欢的味道。</h1><p>从第一杯莫吉托开始，发现调酒的乐趣。<br>跟着步骤调一杯，也分享你的拿手一杯。</p><button class=\"primary\" onclick=\"openDrink(0)\">开始我的第一杯 ↗</button></div><div class=\"hero-art\" id=\"heroart\"></div></section><section id=\"explore\"><div class=\"toolbar\"><div><h2 id=\"listtitle\">今晚，想喝点什么？</h2><div class=\"sub\" id=\"listsub\">34 款酒单 · 清晰步骤 · 在家也能轻松复刻</div></div><input id=\"search\" class=\"search\" placeholder=\"⌕  搜索酒名、基酒或原料\" aria-label=\"搜索配方\"></div><div id=\"filters\" class=\"filters\"></div><div class=\"grid\" id=\"grid\"></div></section><section id=\"community\" class=\"hidden\"><div class=\"community-head\"><button class=\"primary postbutton\" onclick=\"openPost()\">＋ 晒出我的一杯</button><div class=\"eyebrow\">MADE BY YOU</div><h2 style=\"margin-top:12px\">微醺广场</h2><p class=\"sub\">每一杯亲手调的酒，都值得被看见。</p></div><div id=\"feed\" class=\"community-grid\"></div></section><div class=\"bottom-note\"><span>调一杯 · 34 款灵感酒单<br>配方参考 IBA / TheCocktailDB，摄影出处见详情。</span><span>仅限成年人 · 理性饮酒 · 酒后不开车</span></div></main><div class=\"mobile-nav\" id=\"mobilenav\"><button class=\"active\" data-view=\"explore\"><b>⌘</b>探索酒单</button><button data-view=\"community\"><b>♧</b>微醺广场</button><button data-view=\"saved\"><b>♡</b>我的收藏</button></div><div class=\"modal\" id=\"modal\"><div class=\"sheet\"><button class=\"close\" aria-label=\"关闭\" onclick=\"closeModal()\">×</button><div id=\"detail\"></div></div></div><div class=\"toast\" id=\"toast\" role=\"status\"></div><script>\nconst drinks=[{\"name\": \"莫吉托\", \"en\": \"MOJITO\", \"base\": \"朗姆酒\", \"taste\": \"清新酸甜\", \"time\": 5, \"level\": \"新手友好\", \"color\": \"#a7c664\", \"bg\": \"#e5eadb\", \"type\": \"high\", \"ingredients\": [[\"白朗姆酒\", \"45 ml\"], [\"青柠汁\", \"25 ml\"], [\"糖浆\", \"15 ml\"], [\"薄荷叶\", \"8–10 片\"], [\"苏打水\", \"约 60 ml\"], [\"碎冰\", \"适量\"]], \"steps\": [\"将薄荷叶和糖浆放入杯中，轻压释放香气，避免碾碎出苦味。\", \"加入青柠汁、白朗姆酒与碎冰，用吧勺搅拌均匀。\", \"加入苏打水，轻轻提拉搅拌；补满碎冰，用薄荷和青柠片装饰。\"], \"desc\": \"薄荷的清凉与青柠的酸香，给夜晚按下清爽键。\", \"tip\": \"没有捣棒？用木勺柄轻压薄荷即可。\", \"photo\": \"/images/11000.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11000\", \"credit\": \"anilaha https://pixabay.com/users/anilaha-16242978/\", \"photoSource\": \"https://pixabay.com/photos/cocktail-mojito-cocktail-recipe-5096281/\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11000\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"尼格罗尼\", \"en\": \"NEGRONI\", \"base\": \"金酒\", \"taste\": \"浓郁苦甜\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#be492a\", \"bg\": \"#eee0d1\", \"type\": \"short\", \"ingredients\": [[\"金酒\", \"30 ml\"], [\"金巴利\", \"30 ml\"], [\"甜红味美思\", \"30 ml\"], [\"大冰块\", \"1 块\"], [\"橙皮\", \"1 片\"]], \"steps\": [\"搅拌杯中加入金酒、金巴利和甜红味美思。\", \"加入足量冰块，搅拌约 20–30 秒至充分冷却。\", \"滤入装有大冰块的古典杯，挤出橙皮精油并放入杯中。\"], \"desc\": \"三种风味，等量相遇。苦甜交织的意式经典。\", \"tip\": \"搅拌冷却即可，无需摇和。\", \"photo\": \"/images/11003.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11003\", \"credit\": \"TheCocktailDB.com\", \"photoSource\": \"https://www.thecocktaildb.com/drink/11003\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11003\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"玛格丽特\", \"en\": \"MARGARITA\", \"base\": \"龙舌兰\", \"taste\": \"酸爽果香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#d7cb8b\", \"bg\": \"#e8e5d9\", \"type\": \"coupe\", \"ingredients\": [[\"龙舌兰\", \"50 ml\"], [\"橙味利口酒\", \"20 ml\"], [\"青柠汁\", \"25 ml\"], [\"盐\", \"少许\"], [\"冰块\", \"适量\"]], \"steps\": [\"用青柠擦湿杯口一半，轻蘸盐做半圈盐边。\", \"将龙舌兰、橙味利口酒和青柠汁加入摇壶，放入冰块。\", \"用力摇和 10–15 秒，滤入预冷的杯中，饰以青柠片。\"], \"desc\": \"酸爽、明亮，杯口一点盐让柑橘香气更鲜活。\", \"tip\": \"先做半圈盐边，方便选择不同口感。\", \"photo\": \"/images/11007.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11007\", \"credit\": \"Cocktailmarler\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Klassiche_Margarita.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11007\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"日出龙舌兰\", \"en\": \"TEQUILA SUNRISE\", \"base\": \"龙舌兰\", \"taste\": \"甜美果香\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#ed9d40\", \"bg\": \"#f0e2ce\", \"type\": \"high\", \"ingredients\": [[\"龙舌兰\", \"45 ml\"], [\"橙汁\", \"90 ml\"], [\"红石榴糖浆\", \"15 ml\"], [\"冰块\", \"适量\"]], \"steps\": [\"高球杯装满冰块，倒入龙舌兰和橙汁，轻轻搅拌。\", \"沿杯壁缓缓倒入红石榴糖浆，让其自然沉底。\", \"不要再次搅拌，保留日出般的渐层，用橙片装饰。\"], \"desc\": \"一杯装下橙红日出，漂亮的渐层也能轻松完成。\", \"tip\": \"糖浆最后放，才能留下自然渐层。\", \"photo\": \"/images/13621.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/13621\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/13621\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/13621\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"金汤力\", \"en\": \"GIN & TONIC\", \"base\": \"金酒\", \"taste\": \"清冽微苦\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#d3dfb9\", \"bg\": \"#e3e8df\", \"type\": \"high\", \"ingredients\": [[\"金酒\", \"45 ml\"], [\"汤力水\", \"120 ml\"], [\"青柠片\", \"1–2 片\"], [\"冰块\", \"适量\"]], \"steps\": [\"高球杯装满冰块，倒入金酒。\", \"缓慢倒入冰镇汤力水，轻轻搅拌一次。\", \"加入青柠片装饰，立即享用。\"], \"desc\": \"气泡跳跃，杜松与柑橘香气清晰舒展。\", \"tip\": \"汤力水充分冰镇，气泡口感更好。\", \"photo\": \"/images/11403.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11403\", \"credit\": \"pxhere.com\", \"photoSource\": \"https://pxhere.com/en/photo/1556755\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11403\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"威士忌酸\", \"en\": \"WHISKEY SOUR\", \"base\": \"威士忌\", \"taste\": \"柔和酸甜\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#c99039\", \"bg\": \"#ece0cf\", \"type\": \"short\", \"ingredients\": [[\"波本威士忌\", \"50 ml\"], [\"柠檬汁\", \"25 ml\"], [\"糖浆\", \"20 ml\"], [\"冰块\", \"适量\"]], \"steps\": [\"将威士忌、鲜榨柠檬汁和糖浆倒入摇壶。\", \"加入足量冰块，用力摇和 10–15 秒。\", \"滤入装有新冰块的古典杯，以柠檬皮装饰。\"], \"desc\": \"威士忌的醇厚与柠檬的明亮，恰好相互平衡。\", \"tip\": \"本版不含生蛋清，适合居家入门。\", \"photo\": \"/images/11004.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11004\", \"credit\": \"Ralf Roletschek https://www.wikidata.org/wiki/Q15080600\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:15-09-26-RalfR-WLC-0191.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11004\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"大都会\", \"en\": \"COSMOPOLITAN\", \"base\": \"伏特加\", \"taste\": \"莓果酸甜\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#c76879\", \"bg\": \"#eedfe0\", \"type\": \"coupe\", \"ingredients\": [[\"柑橘风味伏特加\", \"40 ml\"], [\"橙味利口酒\", \"15 ml\"], [\"蔓越莓汁\", \"30 ml\"], [\"青柠汁\", \"15 ml\"], [\"冰块\", \"适量\"]], \"steps\": [\"将所有液体材料加入摇壶。\", \"加冰摇和 10–15 秒，至壶壁充分变冷。\", \"滤入预冷的鸡尾酒杯，挤橙皮精油装饰。\"], \"desc\": \"一抹温柔的粉红，藏着明快利落的柑橘香。\", \"tip\": \"蔓越莓汁含糖量不同，可按口味微调。\", \"photo\": \"/images/17196.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17196\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17196\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17196\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"青柠薄荷气泡\", \"en\": \"LIME MINT FIZZ · 0%\", \"base\": \"无酒精\", \"taste\": \"清新气泡\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#c2d79b\", \"bg\": \"#e3e8d9\", \"type\": \"high\", \"ingredients\": [[\"青柠汁\", \"25 ml\"], [\"糖浆\", \"15 ml\"], [\"薄荷叶\", \"8 片\"], [\"苏打水\", \"120 ml\"], [\"冰块\", \"适量\"]], \"steps\": [\"杯中加入薄荷叶、糖浆与青柠汁，轻压薄荷。\", \"加入冰块，倒入冰镇苏打水。\", \"轻轻搅拌，用青柠片和薄荷装饰。\"], \"desc\": \"不含酒精，也有一杯仪式感。清爽适合每个夜晚。\", \"tip\": \"糖浆可少量添加，再按喜好调整。\", \"photo\": \"/images/11000.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11000\", \"credit\": \"anilaha https://pixabay.com/users/anilaha-16242978/\", \"photoSource\": \"https://pixabay.com/photos/cocktail-mojito-cocktail-recipe-5096281/\", \"photoNote\": \"同风格实拍参考\", \"recipeSource\": \"\", \"sourceLabel\": \"本应用 · 无酒精居家配方\"}, {\"name\": \"代基里\", \"en\": \"DAIQUIRI\", \"base\": \"朗姆酒\", \"taste\": \"明亮酸甜\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"白朗姆酒\", \"60 ml\"], [\"青柠汁\", \"20 ml\"], [\"细砂糖\", \"2 吧勺\"]], \"steps\": [\"预冷酒杯，将除冰块和装饰外的配方原料量入摇壶。\", \"加入足量冰块，用力摇和约 10–15 秒，至壶壁充分变冷。\", \"用滤冰器滤入酒杯，按小贴士装饰后饮用。\"], \"desc\": \"明亮酸甜风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"先将糖充分搅溶，再加冰摇和。\", \"photo\": \"/images/11006.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11006\", \"credit\": \"Will Shenton\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Classic_Daiquiri_in_Cocktail_Glass.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://iba-world.com/iba-cocktail/daiquiri/\", \"sourceLabel\": \"IBA · 配方参考\"}, {\"name\": \"咖啡马天尼\", \"en\": \"ESPRESSO MARTINI\", \"base\": \"伏特加\", \"taste\": \"醇香咖啡\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"50 ml\"], [\"咖啡利口酒\", \"30 ml\"], [\"糖浆\", \"10 ml\"], [\"浓缩咖啡\", \"1 份（约 30 ml）\"]], \"steps\": [\"预冷酒杯，将除冰块和装饰外的配方原料量入摇壶。\", \"加入足量冰块，用力摇和约 10–15 秒，至壶壁充分变冷。\", \"用滤冰器滤入酒杯，按小贴士装饰后饮用。\"], \"desc\": \"醇香咖啡风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"咖啡先稍微放凉；充分摇和可形成细密泡沫，饰以三粒咖啡豆。\", \"photo\": \"/images/17212.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17212\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17212\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://iba-world.com/iba-cocktail/espresso-martini/\", \"sourceLabel\": \"IBA · 配方参考\"}, {\"name\": \"长岛冰茶\", \"en\": \"LONG ISLAND ICED TEA\", \"base\": \"多基酒\", \"taste\": \"柑橘可乐\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"15 ml\"], [\"龙舌兰\", \"15 ml\"], [\"白朗姆酒\", \"15 ml\"], [\"金酒\", \"15 ml\"], [\"橙味利口酒\", \"15 ml\"], [\"柠檬汁\", \"25 ml\"], [\"糖浆\", \"30 ml\"], [\"可乐\", \"适量补足\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"柑橘可乐风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"将可乐留到最后添加；本款含多种烈酒，酒感较强。\", \"photo\": \"/images/17204.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17204\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17204\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://iba-world.com/iba-cocktail/long-island-iced-tea/\", \"sourceLabel\": \"IBA · 配方参考\"}, {\"name\": \"古典\", \"en\": \"OLD FASHIONED\", \"base\": \"威士忌\", \"taste\": \"醇厚苦甜\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"波本威士忌\", \"45 ml\"], [\"方糖\", \"1 块\"], [\"芳香苦精\", \"2 dash\"], [\"水\", \"约 5 ml\"]], \"steps\": [\"预冷酒杯，准备好配方中的酒及调味原料。\", \"将原料与冰块放入搅拌杯，搅拌约 20–30 秒至冷却；杯中直调款按小贴士操作。\", \"滤入酒杯，按小贴士加入装饰。\"], \"desc\": \"醇厚苦甜风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"先用水与苦精将方糖溶解，再加酒与大冰块搅拌，最后挤橙皮精油。\", \"photo\": \"/images/11001.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11001\", \"credit\": \"Dave M\", \"photoSource\": \"https://www.thecocktaildb.com/drink/11001-Old-Fashioned-Cocktail\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11001\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"曼哈顿\", \"en\": \"MANHATTAN\", \"base\": \"威士忌\", \"taste\": \"浓郁酒香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"黑麦威士忌\", \"50 ml\"], [\"甜红味美思\", \"20 ml\"], [\"芳香苦精\", \"1 dash\"]], \"steps\": [\"预冷酒杯，准备好配方中的酒及调味原料。\", \"将原料与冰块放入搅拌杯，搅拌约 20–30 秒至冷却；杯中直调款按小贴士操作。\", \"滤入酒杯，按小贴士加入装饰。\"], \"desc\": \"浓郁酒香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"滤入预冷的鸡尾酒杯，用酒渍樱桃装饰。\", \"photo\": \"/images/11008.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11008\", \"credit\": \"Sarah Stierch (CC BY 4.0)\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Oak_Fired_Manhattan_-_Stierch_1.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11008\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"莫斯科骡子\", \"en\": \"MOSCOW MULE\", \"base\": \"伏特加\", \"taste\": \"姜香清爽\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"45 ml\"], [\"青柠汁\", \"10 ml\"], [\"姜汁啤酒（无酒精）\", \"120 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"姜香清爽风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"使用无酒精姜汁啤酒作调饮料，青柠片装饰；不必使用铜杯。\", \"photo\": \"/images/11009.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11009\", \"credit\": \"Will Shenton\\r\\n\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Moscow_Mule_at_Rye,_San_Francisco.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11009\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"椰林飘香\", \"en\": \"PINA COLADA\", \"base\": \"朗姆酒\", \"taste\": \"热带椰香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"白朗姆酒\", \"50 ml\"], [\"椰奶油（cream of coconut）\", \"30 ml\"], [\"菠萝汁\", \"50 ml\"], [\"碎冰\", \"约 1 杯\"]], \"steps\": [\"将酒、果汁和椰奶油量入搅拌机。\", \"加入碎冰，搅打成细腻均匀的冰沙。\", \"倒入高杯，用菠萝片装饰，及时享用。\"], \"desc\": \"热带椰香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"使用调酒用甜椰奶油，和普通椰奶不同；饰以菠萝片。\", \"photo\": \"/images/17207.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17207\", \"credit\": \"TheCocktailDB\", \"photoSource\": \"https://www.thecocktaildb.com/images/media/drink/upgsue1668419912.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17207\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"迈泰\", \"en\": \"MAI TAI\", \"base\": \"朗姆酒\", \"taste\": \"坚果果香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"琥珀朗姆酒\", \"30 ml\"], [\"深色朗姆酒\", \"30 ml\"], [\"橙味库拉索利口酒\", \"15 ml\"], [\"杏仁糖浆\", \"15 ml\"], [\"青柠汁\", \"30 ml\"], [\"糖浆\", \"7.5 ml\"]], \"steps\": [\"预冷酒杯，将除冰块和装饰外的配方原料量入摇壶。\", \"加入足量冰块，用力摇和约 10–15 秒，至壶壁充分变冷。\", \"用滤冰器滤入酒杯，按小贴士装饰后饮用。\"], \"desc\": \"坚果果香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"杏仁糖浆可能含坚果；滤入装有碎冰的杯中，用薄荷装饰。\", \"photo\": \"/images/11690.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11690\", \"credit\": \"Johnny Silvercloud https://www.flickr.com/people/116193477@N08\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Mai_Tai_(16304400706).jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://iba-world.com/iba-cocktail/mai-tai/\", \"sourceLabel\": \"IBA · 配方参考\"}, {\"name\": \"阿佩罗气泡\", \"en\": \"APEROL SPRITZ\", \"base\": \"起泡酒\", \"taste\": \"橙香微苦\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"普罗塞克起泡酒\", \"90 ml\"], [\"阿佩罗开胃酒\", \"60 ml\"], [\"苏打水\", \"30 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"橙香微苦风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"酒杯装满冰，依次加入起泡酒、阿佩罗和苏打水；用橙片装饰。\", \"photo\": \"/images/178325.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/178325\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/178325\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/178325\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"金菲士\", \"en\": \"GIN FIZZ\", \"base\": \"金酒\", \"taste\": \"柠檬气泡\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"金酒\", \"45 ml\"], [\"柠檬汁\", \"30 ml\"], [\"糖浆\", \"10 ml\"], [\"苏打水\", \"约 80 ml\"]], \"steps\": [\"将不含气泡的配方原料倒入摇壶。\", \"加入冰块摇和约 10–15 秒，再滤入准备好的酒杯。\", \"最后缓慢补入苏打水或起泡酒，轻轻搅拌并装饰。\"], \"desc\": \"柠檬气泡风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"先摇和金酒、柠檬汁和糖浆；苏打水最后加入。\", \"photo\": \"/images/11410.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11410\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:15-09-26-RalfR-WLC-0032.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11410\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"汤姆柯林斯\", \"en\": \"TOM COLLINS\", \"base\": \"金酒\", \"taste\": \"清爽酸甜\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"金酒\", \"45 ml\"], [\"柠檬汁\", \"30 ml\"], [\"糖浆\", \"15 ml\"], [\"苏打水\", \"60 ml\"]], \"steps\": [\"将不含气泡的配方原料倒入摇壶。\", \"加入冰块摇和约 10–15 秒，再滤入准备好的酒杯。\", \"最后缓慢补入苏打水或起泡酒，轻轻搅拌并装饰。\"], \"desc\": \"清爽酸甜风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"滤入装有冰块的柯林斯杯，再添苏打水，饰以柠檬片。\", \"photo\": \"/images/12402.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/12402\", \"credit\": \"Will Shenton\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Tom_Collins.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/12402\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"自由古巴\", \"en\": \"CUBA LIBRE\", \"base\": \"朗姆酒\", \"taste\": \"青柠可乐\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"白朗姆酒\", \"50 ml\"], [\"青柠汁\", \"10 ml\"], [\"可乐\", \"120 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"青柠可乐风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"使用冰镇可乐，轻轻提拉搅拌以保留气泡。\", \"photo\": \"/images/11288.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11288\", \"credit\": \"Martin Belam (currybet)\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Cuba_Libre.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11288\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"蓝色珊瑚礁\", \"en\": \"BLUE LAGOON\", \"base\": \"伏特加\", \"taste\": \"蓝色柑橘\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"30 ml\"], [\"蓝橙利口酒\", \"20 ml\"], [\"柠檬汽水\", \"100 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"蓝色柑橘风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"蓝橙利口酒含酒精；柠檬汽水最后倒入。\", \"photo\": \"/images/11117.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11117\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/11117\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11117\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"白俄罗斯\", \"en\": \"WHITE RUSSIAN\", \"base\": \"伏特加\", \"taste\": \"奶香咖啡\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"50 ml\"], [\"咖啡利口酒\", \"20 ml\"], [\"淡奶油\", \"30 ml\"]], \"steps\": [\"古典杯中放入冰块，加入伏特加和咖啡利口酒。\", \"轻轻搅拌至酒液充分冷却。\", \"沿吧勺背缓缓倒入淡奶油，按喜好保留分层或搅匀。\"], \"desc\": \"奶香咖啡风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"淡奶油沿吧勺背缓缓倒入，可保留分层；饮用前按喜好搅匀。\", \"photo\": \"/images/12528.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/12528\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/12528\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/12528\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"黑俄罗斯\", \"en\": \"BLACK RUSSIAN\", \"base\": \"伏特加\", \"taste\": \"浓郁咖啡\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"50 ml\"], [\"咖啡利口酒\", \"20 ml\"]], \"steps\": [\"预冷酒杯，准备好配方中的酒及调味原料。\", \"将原料与冰块放入搅拌杯，搅拌约 20–30 秒至冷却；杯中直调款按小贴士操作。\", \"滤入酒杯，按小贴士加入装饰。\"], \"desc\": \"浓郁咖啡风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"直接在放有大冰块的古典杯中搅拌即可。\", \"photo\": \"/images/11102.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11102\", \"credit\": \"Will Shenton\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Black_Russian.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11102\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"血腥玛丽\", \"en\": \"BLOODY MARY\", \"base\": \"伏特加\", \"taste\": \"鲜咸辛香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"45 ml\"], [\"番茄汁\", \"90 ml\"], [\"柠檬汁\", \"15 ml\"], [\"伍斯特酱\", \"2 dash\"], [\"辣椒汁\", \"少许\"], [\"盐和黑胡椒\", \"少许\"]], \"steps\": [\"将酒、果汁及少量调味料倒入大杯。\", \"加入冰块，用两只杯子轻柔来回倒换几次混匀，不要用力摇和。\", \"试味后微调盐、黑胡椒和辣度，再装饰出杯。\"], \"desc\": \"鲜咸辛香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"调味料先少量加入，再按口味调整；饰以芹菜梗。\", \"photo\": \"/images/11113.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11113\", \"credit\": \"TheCocktialDB.com\", \"photoSource\": \"https://www.thecocktaildb.com/drink/11113-Bloody-Mary\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11113\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"性感海滩\", \"en\": \"SEX ON THE BEACH\", \"base\": \"伏特加\", \"taste\": \"蜜桃莓果\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"伏特加\", \"40 ml\"], [\"蜜桃利口酒\", \"20 ml\"], [\"橙汁\", \"40 ml\"], [\"蔓越莓汁\", \"40 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"蜜桃莓果风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"杯中加足冰块，轻轻搅匀，饰以橙片。\", \"photo\": \"/images/12754.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/12754\", \"credit\": \"TheCocktailDB\", \"photoSource\": \"https://www.thecocktaildb.com/images/media/drink/fi67641668420787.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/12754\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"帕洛玛\", \"en\": \"PALOMA\", \"base\": \"龙舌兰\", \"taste\": \"西柚清爽\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"龙舌兰\", \"50 ml\"], [\"青柠汁\", \"5 ml\"], [\"西柚汽水\", \"100 ml\"], [\"盐\", \"一小撮\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"西柚清爽风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"可用青柠擦湿半圈杯口并蘸盐；西柚汽水最后加入。\", \"photo\": \"/images/17253.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17253\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17253\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17253\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"法式75\", \"en\": \"FRENCH 75\", \"base\": \"金酒\", \"taste\": \"柑橘气泡\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"金酒\", \"30 ml\"], [\"柠檬汁\", \"15 ml\"], [\"糖浆\", \"15 ml\"], [\"香槟或干型起泡酒\", \"60 ml\"]], \"steps\": [\"将不含气泡的配方原料倒入摇壶。\", \"加入冰块摇和约 10–15 秒，再滤入准备好的酒杯。\", \"最后缓慢补入苏打水或起泡酒，轻轻搅拌并装饰。\"], \"desc\": \"柑橘气泡风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"先摇和前三种原料，滤入笛形杯，再缓缓加入起泡酒。\", \"photo\": \"/images/17197.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17197\", \"credit\": \"robert84ak https://pixabay.com/de/users/robert84ak-16722616/\", \"photoSource\": \"https://pixabay.com/de/photos/champagner-cocktail-french-75-5374793/\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17197\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"边车\", \"en\": \"SIDECAR\", \"base\": \"白兰地\", \"taste\": \"柑橘醇香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"干邑白兰地\", \"50 ml\"], [\"橙味利口酒\", \"20 ml\"], [\"柠檬汁\", \"20 ml\"]], \"steps\": [\"预冷酒杯，将除冰块和装饰外的配方原料量入摇壶。\", \"加入足量冰块，用力摇和约 10–15 秒，至壶壁充分变冷。\", \"用滤冰器滤入酒杯，按小贴士装饰后饮用。\"], \"desc\": \"柑橘醇香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"滤入预冷的鸡尾酒杯，可选择做半圈糖边。\", \"photo\": \"/images/12196.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/12196\", \"credit\": \"Michael Styne https://www.flickr.com/photos/mstyne/\", \"photoSource\": \"https://www.flickr.com/photos/mstyne/29716525626/in/dateposted/\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/12196\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"新加坡司令\", \"en\": \"SINGAPORE SLING\", \"base\": \"金酒\", \"taste\": \"热带果香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"金酒\", \"30 ml\"], [\"樱桃利口酒\", \"15 ml\"], [\"君度橙酒\", \"7.5 ml\"], [\"廊酒\", \"7.5 ml\"], [\"菠萝汁\", \"120 ml\"], [\"青柠汁\", \"15 ml\"], [\"红石榴糖浆\", \"10 ml\"], [\"芳香苦精\", \"1 dash\"]], \"steps\": [\"预冷酒杯，将除冰块和装饰外的配方原料量入摇壶。\", \"加入足量冰块，用力摇和约 10–15 秒，至壶壁充分变冷。\", \"用滤冰器滤入酒杯，按小贴士装饰后饮用。\"], \"desc\": \"热带果香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"材料较多，先逐项量好；滤入加冰的高杯，饰以菠萝与樱桃。\", \"photo\": \"/images/12214.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/12214\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/12214\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://iba-world.com/iba-cocktail/singapore-sling/\", \"sourceLabel\": \"IBA · 配方参考\"}, {\"name\": \"美式开胃酒\", \"en\": \"AMERICANO\", \"base\": \"开胃酒\", \"taste\": \"清爽苦甜\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"金巴利\", \"30 ml\"], [\"甜红味美思\", \"30 ml\"], [\"苏打水\", \"约 60 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"清爽苦甜风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"在加冰的古典杯中先混合两种酒，再补苏打水，用橙片装饰。\", \"photo\": \"/images/15941.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/15941\", \"credit\": \"Author - Cher37 https://commons.wikimedia.org/wiki/File:Martini_Americano.jpg\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Martini_Americano.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/15941\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"贝利尼\", \"en\": \"BELLINI\", \"base\": \"起泡酒\", \"taste\": \"柔和蜜桃\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"白桃果泥\", \"50 ml\"], [\"普罗塞克起泡酒\", \"100 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"柔和蜜桃风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"果泥与起泡酒都要预先冰镇，杯中不加冰，轻轻搅匀避免溢出。\", \"photo\": \"/images/17195.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17195\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17195\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17195\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"含羞草\", \"en\": \"MIMOSA\", \"base\": \"起泡酒\", \"taste\": \"明亮橙香\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"鲜榨橙汁\", \"75 ml\"], [\"干型起泡酒\", \"75 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"明亮橙香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"使用冰镇原料，在笛形杯中缓缓混合，不额外加冰。\", \"photo\": \"/images/17205.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17205\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17205\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17205\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"暗黑风暴\", \"en\": \"DARK AND STORMY\", \"base\": \"朗姆酒\", \"taste\": \"浓郁姜香\", \"time\": 3, \"level\": \"新手友好\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"深色朗姆酒\", \"60 ml\"], [\"姜汁啤酒（无酒精）\", \"100 ml\"]], \"steps\": [\"备好配方原料，按小贴士选择杯型与冰块。\", \"量入基酒及非气泡调味原料，轻轻搅拌均匀。\", \"如含汽水或起泡酒，最后缓慢加入，轻轻提拉一次并装饰。\"], \"desc\": \"浓郁姜香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"先倒姜汁啤酒，再沿吧勺背倒入深色朗姆酒，形成深浅层次。\", \"photo\": \"/images/17211.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/17211\", \"credit\": \"TheCocktailDB 社区\", \"photoSource\": \"https://www.thecocktaildb.com/drink/17211\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/17211\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}, {\"name\": \"白兰地亚历山大\", \"en\": \"BRANDY ALEXANDER\", \"base\": \"白兰地\", \"taste\": \"巧克力奶香\", \"time\": 5, \"level\": \"轻松进阶\", \"color\": \"#bd8151\", \"bg\": \"#e8e2d7\", \"type\": \"high\", \"ingredients\": [[\"干邑白兰地\", \"30 ml\"], [\"深色可可利口酒\", \"30 ml\"], [\"淡奶油\", \"30 ml\"]], \"steps\": [\"预冷酒杯，将除冰块和装饰外的配方原料量入摇壶。\", \"加入足量冰块，用力摇和约 10–15 秒，至壶壁充分变冷。\", \"用滤冰器滤入酒杯，按小贴士装饰后饮用。\"], \"desc\": \"巧克力奶香风格的经典配方，适合为居家酒单增加一个新选择。\", \"tip\": \"滤入预冷杯中，表面撒少量肉豆蔻粉；含乳制品。\", \"photo\": \"/images/11016.jpg\", \"source\": \"https://www.thecocktaildb.com/drink/11016\", \"credit\": \"Will Shenton\", \"photoSource\": \"https://commons.wikimedia.org/wiki/File:Brandy_Alexander_on_the_Rocks.jpg\", \"photoNote\": \"成品实拍参考\", \"recipeSource\": \"https://www.thecocktaildb.com/drink/11016\", \"sourceLabel\": \"TheCocktailDB · 经典配方参考\"}];\nfunction art(d){return '<img class=\"drink-photo\" src=\"'+d.photo+'\" alt=\"'+d.name+' · '+d.photoNote+'\" loading=\"lazy\" decoding=\"async\" width=\"720\" height=\"720\">'}\n\nlet saved;try{saved=JSON.parse(localStorage.getItem('mix-saved')||'[]')}catch{saved=[]}let view='explore',filter='全部',current=0,posts=[],timerId;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n$('#heroart').innerHTML=art(drinks[0]);function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}\nfunction render(){let q=$('#search').value.trim().toLowerCase();$('#filters').innerHTML=['全部','新手友好','金酒','朗姆酒','龙舌兰','威士忌','伏特加','白兰地','起泡酒','开胃酒','多基酒','无酒精'].map(f=>'<button class=\"'+(filter===f?'active':'')+'\" onclick=\"setFilter(\\''+f+'\\')\">'+f+'</button>').join('');let list=drinks.map((d,i)=>({d,i})).filter(({d,i})=>(view!=='saved'||saved.includes(i))&&(filter==='全部'||d.base===filter||d.level===filter)&&JSON.stringify(d).toLowerCase().includes(q));$('#grid').innerHTML=list.map(({d,i})=>'<article class=\"card\" tabindex=\"0\" role=\"button\" aria-label=\"查看'+d.name+'配方\" onclick=\"openDrink('+i+')\" onkeydown=\"if(event.key===\\'Enter\\')openDrink('+i+')\"><div class=\"art\" style=\"--bg:'+d.bg+'\">'+art(d)+'<button class=\"save\" aria-label=\"收藏'+d.name+'\" onclick=\"event.stopPropagation();toggleSave('+i+')\">'+(saved.includes(i)?'♥':'♡')+'</button></div><div class=\"cardbody\"><div class=\"en\">'+d.en+'</div><h3>'+d.name+'</h3><div class=\"tags\"><span>'+d.taste+'</span><span>'+d.time+' 分钟 · '+d.level+'</span></div></div></article>').join('')||'<p class=\"empty\">'+(view==='saved'?'还没有匹配的收藏，点击配方上的 ♡ 收好你的下一杯。':'没有找到配方，试试其他酒名或原料。')+'</p>'}\nfunction setFilter(f){filter=f;render()}function toggleSave(i){if(saved.includes(i))saved=saved.filter(x=>x!==i);else saved.push(i);try{localStorage.setItem('mix-saved',JSON.stringify(saved))}catch{}render();toast(saved.includes(i)?'已加入我的收藏':'已取消收藏')}\nfunction setView(v){view=v;$('#hero').classList.toggle('hidden',v!=='explore');$('#explore').classList.toggle('hidden',v==='community');$('#community').classList.toggle('hidden',v!=='community');$('#listtitle').textContent=v==='saved'?'我的私藏酒单':'今晚，想喝点什么？';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));filter='全部';$('#search').value='';render();if(v==='community')loadFeed();window.scrollTo(0,0)}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#search').oninput=render;\nfunction closeModal(){if(timerId)clearInterval(timerId);$('#modal').classList.remove('open');document.body.style.overflow=''}function showModal(){ $('#modal').classList.add('open');document.body.style.overflow='hidden';$('#modal').scrollTop=0;$('.close').focus()}$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});\nfunction form(i){return '<form id=\"postform\"><label>你的昵称<input name=\"name\" maxlength=\"24\" placeholder=\"怎么称呼你\" required></label>'+(i===undefined?'<label>这次调了哪一杯<select name=\"drink\">'+drinks.map((d,j)=>'<option value=\"'+j+'\">'+d.name+'</option>').join('')+'</select></label>':'<input type=\"hidden\" name=\"drink\" value=\"'+i+'\">')+'<label>调酒心得<textarea name=\"text\" maxlength=\"1000\" placeholder=\"味道如何？有什么独家小技巧？\" required></textarea></label><label>晒成品照片（可选，最大 8 MB）<input name=\"photo\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/heic,image/heif\"></label><div id=\"photoPreview\"></div><button class=\"primary\" type=\"submit\">发布我的一杯 ↗</button><span id=\"status\" role=\"status\"></span></form>'}\nfunction bindForm(){let f=$('#postform');f.photo.onchange=()=>{let file=f.photo.files[0];if(file&&file.size>8*1024*1024){toast('请选取小于 8 MB 的照片');f.photo.value=''}};f.onsubmit=async e=>{e.preventDefault();let b=f.querySelector('button');b.disabled=true;b.textContent='正在发布…';$('#status').textContent='';try{let photo=f.photo.files[0],image=null;if(photo){image=await new Promise((resolve,reject)=>{let img=new Image(),url=URL.createObjectURL(photo);img.onload=()=>{let c=document.createElement('canvas'),s=Math.min(1,1200/img.width,1200/img.height);c.width=img.width*s;c.height=img.height*s;c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.82))};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('暂不支持这张图片，请在相册中转换为 JPEG 后重试。'))};img.src=url})}let res=await fetch('/api/posts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.elements.namedItem('name').value,text:f.text.value,drink:Number(f.drink.value),image})});let data=await res.json();if(!res.ok)throw Error(data.error||'发布失败');toast('发布成功，收下这一杯！');if(view==='community')loadFeed();if($('#comments'))loadComments(current);f.reset();}catch(e){$('#status').textContent=e.message}finally{b.disabled=false;b.textContent='发布我的一杯 ↗'}}}\nfunction openDrink(i){current=i;let d=drinks[i];$('#detail').innerHTML='<div class=\"detailtop\"><div class=\"art\" style=\"--bg:'+d.bg+'\">'+art(d)+'</div><div><div class=\"en\">'+d.en+'</div><h2>'+d.name+'</h2><div class=\"sub\">'+d.time+' 分钟 / '+d.level+'</div><p class=\"desc\">'+d.desc+'</p><button class=\"primary\" onclick=\"toggleSave('+i+')\">♡ 收藏这杯配方</button></div></div><div class=\"section\"><h3>准备原料 <span class=\"sub\">/ 1 人份</span></h3><div class=\"ingredients\">'+d.ingredients.map(([a,b])=>'<div class=\"ingredient\"><span>'+a+'</span><span>'+b+'</span></div>').join('')+'</div></div><div class=\"section\"><h3>一步一步，调出好味道</h3><ol class=\"steps\">'+d.steps.map(s=>'<li>'+s+'</li>').join('')+'</ol><button class=\"timer\" id=\"timer\" onclick=\"startTimer()\">◷ 开始 15 秒摇和 / 搅拌计时</button><div class=\"instruction\">调酒小贴士 · '+d.tip+'<br>实拍为出杯效果参考；品牌、比例、杯型与光线会影响实际呈现。</div><div class=\"sources\">'+(d.recipeSource?'<a href=\"'+esc(d.recipeSource)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+esc(d.sourceLabel)+' ↗</a>':'<span>'+esc(d.sourceLabel)+'</span>')+'<br><a href=\"'+esc(d.photoSource)+'\" target=\"_blank\" rel=\"noopener noreferrer\">照片来源：'+esc(d.credit)+' ↗</a><br>配方为居家版本整理，可能与来源中的比例有所不同。</div></div><div class=\"section\"><h3>大家调的这一杯</h3><div id=\"comments\">正在加载评论…</div></div><div class=\"section\"><h3>晒出你的成果</h3>'+form(i)+'</div>';showModal();bindForm();loadComments(i)}\nfunction startTimer(){if(timerId)clearInterval(timerId);let t=15;$('#timer').textContent='还剩 '+t+' 秒';timerId=setInterval(()=>{t--;if(!$('#timer'))return clearInterval(timerId);$('#timer').textContent=t?'还剩 '+t+' 秒':'✓ 时间到，可以出杯啦';if(!t)clearInterval(timerId)},1000)}function comment(p,feed=false){return '<article class=\"comment\"><div class=\"sub\">'+esc(p.name)+' · '+new Date(p.created).toLocaleDateString('zh-CN')+'</div>'+(feed?'<h3>'+esc(drinks[p.drink]?.name||'我的一杯')+'</h3>':'')+'<p>'+esc(p.text)+'</p>'+(p.image?'<img loading=\"lazy\" src=\"/api/photo/'+encodeURIComponent(p.id)+'\" alt=\"'+esc(p.name)+'调制的成品\">':'')+'</article>'}\nasync function loadComments(i){try{let r=await fetch('/api/posts?drink='+i);if(!r.ok)throw Error();let p=await r.json();if($('#comments')&&current===i)$('#comments').innerHTML=p.length?p.map(p=>comment(p)).join(''):'<p class=\"desc\">还没有人分享，成为第一个晒出这杯的人吧。</p>'}catch{if($('#comments'))$('#comments').textContent='评论暂时无法加载，请稍后重新打开。'}}\nasync function loadFeed(){$('#feed').innerHTML='<p class=\"desc\">正在加载大家的作品…</p>';try{let r=await fetch('/api/posts');if(!r.ok)throw Error();posts=await r.json();$('#feed').innerHTML=posts.length?posts.map(p=>comment(p,true)).join(''):'<div class=\"instruction\">广场还在等待第一杯。点击「晒出我的一杯」，上传你亲手调制的作品。</div>'}catch{$('#feed').innerHTML='<p class=\"desc\">暂时无法连接，请稍后再试。<button onclick=\"loadFeed()\">重新加载</button></p>'}}\nfunction openPost(){$('#detail').innerHTML='<div class=\"eyebrow\">SHARE YOUR CREATION</div><h2 style=\"margin:15px 0 24px\">晒出我的一杯</h2>'+form();showModal();bindForm()}render();\n</script></body></html>";
const photos={"11000": "", "11003": "", "11007": "", "13621": "", "11403": "", "11004": "", "17196": "", "11006": "", "17212": "", "17204": "", "11001": "", "11008": "", "11009": "", "17207": "", "11690": "", "178325": "", "11410": "", "12402": "", "11288": "", "11117": "", "12528": "", "11102": "", "11113": "", "12754": "", "17253": "", "17197": "", "12196": "", "12214": "", "15941": "", "17195": "", "17205": "", "17211": "", "11016": ""};
const json=(v,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store'}});
export default {async fetch(request,env){const u=new URL(request.url);try{
if(u.pathname.startsWith('/images/')){const key=u.pathname.split('/').pop().replace(/\.jpg$/,'');const b=photos[key];return b?new Response(Uint8Array.from(atob(b),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'public,max-age=86400','X-Content-Type-Options':'nosniff'}}):new Response('Not found',{status:404})}
if(u.pathname==='/manifest.json')return json({name:'调一杯 · Cocktail Studio',short_name:'调一杯',start_url:'/',display:'standalone',background_color:'#faf8f3',theme_color:'#722f3f',icons:[{src:'/icon.png',sizes:'180x180',type:'image/png',purpose:'any'}]});
if(u.pathname==='/icon.png')return new Response(Uint8Array.from(atob(''),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png'}});
if(u.pathname==='/api/posts'){
if(!env.BUCKET)return json({error:'云端存储尚未连接，请稍后再试'},503);
if(request.method==='GET'){const list=await env.BUCKET.list({prefix:'posts/',limit:200});const rows=(await Promise.all(list.objects.map(async o=>{const v=await env.BUCKET.get(o.key);return v?await v.json():null}))).filter(Boolean).sort((a,b)=>b.created.localeCompare(a.created));return json(rows.filter(p=>!u.searchParams.has('drink')||p.drink===Number(u.searchParams.get('drink'))));}
if(request.method==='POST'){if(request.headers.get('origin')!==u.origin)return json({error:'请求来源不正确'},403);if(Number(request.headers.get('content-length'))>4000000)return json({error:'照片过大'},413);const raw=await request.text();if(raw.length>4000000)return json({error:'照片过大'},413);let b;try{b=JSON.parse(raw)}catch{return json({error:'提交格式不正确'},400)}if(typeof b.name!=='string'||!b.name.trim()||b.name.length>24||typeof b.text!=='string'||!b.text.trim()||b.text.length>1000||!Number.isInteger(b.drink)||b.drink<0||b.drink>=34)return json({error:'请填写昵称、配方和心得'},400);const id=crypto.randomUUID(),created=new Date().toISOString();let image=false;if(b.image){if(typeof b.image!=='string'||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(b.image))return json({error:'图片格式不正确'},400);const s=atob(b.image.split(',')[1]);if(s.length>2800000)return json({error:'压缩后的照片仍过大，请选择较小图片'},413);await env.BUCKET.put('photos/'+id,Uint8Array.from(s,c=>c.charCodeAt(0)),{httpMetadata:{contentType:'image/jpeg'}});image=true}const p={id,name:b.name.trim(),text:b.text.trim(),drink:b.drink,created,image};await env.BUCKET.put('posts/'+id,JSON.stringify(p));return json(p,201)}return json({error:'Method not allowed'},405)}
if(u.pathname.startsWith('/api/photo/')){const id=u.pathname.split('/').pop();if(!/^[a-f0-9-]{36}$/.test(id))return new Response('Not found',{status:404});const o=await env.BUCKET?.get('photos/'+id);return o?new Response(o.body,{headers:{'Content-Type':'image/jpeg','Cache-Control':'private, max-age=3600','X-Content-Type-Options':'nosniff'}}):new Response('Not found',{status:404})}
if(u.pathname!=='/')return new Response('Not found',{status:404});return new Response(page,{headers:{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff'}});
}catch(e){return json({error:'服务暂时不可用，请稍后重试'},500)}}};
